  ('6323e812-8fbd-50e9-b0b6-af029c09ad04', null, (select id from public.skills where slug = 'read-g10-context-clues'), null, 'medium',
   $q$Which detail from paragraph 4 gives an example of an "anomaly"?$q$, $q$[{"text":"a bridge that stretches more at rush hour","is_correct":false,"misconception_token":"opposite-meaning"},{"text":"a beam that stretches more on a quiet night","is_correct":true},{"text":"a computer that stores months of readings","is_correct":false,"misconception_token":"wrong-context-clue"},{"text":"a deck that relaxes after dark each night","is_correct":false,"misconception_token":"opposite-meaning"}]$q$::jsonb, $q$a beam that stretches more on a quiet night$q$, $q$An anomaly is "a reading that breaks the usual pattern without an obvious reason," and the author's example is a beam that "suddenly stretches more on a quiet night." Stretching more at rush hour is part of the normal pattern, so it is not an anomaly.$q$, 'draft', 'acbb901b-766b-5e28-be9b-b69bfc4d60bb')
