  ('de65be77-7137-5fed-9e4e-360538c9b5de', null, (select id from public.skills where slug = 'read-g10-evidence-inference'), null, 'medium',
   $q$Why does the transit office mention the student fare discount?$q$, $q$[{"text":"To argue that fare discounts work better than signal priority.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"To show that students were the main riders of route 14.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"To signal that the ridership increase may not be due to signal priority alone.","is_correct":true},{"text":"To explain why travel time fell from forty-one to thirty-four minutes.","is_correct":false,"misconception_token":"confuses-cause-effect"}]$q$::jsonb, $q$To signal that the ridership increase may not be due to signal priority alone.$q$, $q$The discount "began the same year," so it could also have raised ridership, which makes the twelve percent gain harder to credit fully to signal priority. A fare discount would not shorten travel time, so it cannot explain that change.$q$, 'draft', '2a608e7a-88c7-5ab8-b406-52d9b9a1ba2e')
