values
  ('954460a1-2562-5d20-ae84-22b6b670f18e', null, (select id from public.skills where slug = 'read-g10-figurative-language'), null, 'hard',
   $q$The director calls the rehearsal "a very educational evening." What is the tone of this euphemism, and what does it reveal?$q$, $q$[{"text":"It is wry and good-humored, admitting the night went badly while hinting it was useful.","is_correct":true},{"text":"It is purely factual, revealing that the cast attended a lecture.","is_correct":false,"misconception_token":"literal-reading"},{"text":"It is boastful, revealing that the rehearsal went better than planned.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"It is angry, revealing that the director plans to cancel the play.","is_correct":false,"misconception_token":"misreads-tone"}]$q$::jsonb, $q$It is wry and good-humored, admitting the night went badly while hinting it was useful.$q$, $q$The director speaks "with a tired smile" after a frozen board and a late finish, so "educational" gently admits the problems while suggesting lessons were learned. The rehearsal ran "well past schedule," so it did not go better than planned.$q$, 'draft', '621ead57-d96b-532a-8dc5-8ef6ef0fc115')
