  ('649e04f8-ea82-5c88-9995-1109d4ae8d37', null, (select id from public.skills where slug = 'read-g10-figurative-language'), null, 'medium',
   $q$What does the euphemism "a lot of personality" usually mean on the shelter's kennel cards?$q$, $q$[{"text":"The animal is the friendliest and easiest pet in the shelter.","is_correct":false,"misconception_token":"reverses-connotation"},{"text":"The animal has behavior that is challenging and not yet understood.","is_correct":true},{"text":"The animal has been given a funny name by the volunteers.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The animal has unusual markings that make it stand out visually.","is_correct":false,"misconception_token":"misreads-target"}]$q$::jsonb, $q$The animal has behavior that is challenging and not yet understood.$q$, $q$The passage says such a dog "was usually a puzzle that nobody had solved yet," and Biscuit's constant barking proves the point. The phrase sounds flattering, but it signals difficulty rather than ease.$q$, 'draft', '2e36ce9a-2dca-5cff-a90b-752aeb4ce2be')
