values
  ('d3d5fd58-4473-5822-9f26-5cc3d0bcc4e0', null, (select id from public.skills where slug = 'read-g10-figurative-language'), null, 'easy',
   $q$The author says the merchant saw frozen ponds as "a harvest waiting for the right market." What does this metaphor mean?$q$, $q$[{"text":"He thought the ice was a nuisance that no one would ever buy.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"He planted crops around the edges of the ponds each spring.","is_correct":false,"misconception_token":"literal-reading"},{"text":"He saw the ice as a valuable crop that could be gathered and sold.","is_correct":true},{"text":"He believed the ponds should be drained so that farms could expand.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$He saw the ice as a valuable crop that could be gathered and sold.$q$, $q$A harvest is something gathered for its value, matching how he cut ice and shipped it to buyers. The passage says it was his neighbors, not the merchant, who saw the ponds "as a nuisance."$q$, 'draft', 'a64d80fc-e58f-572f-aac4-f572782d3a6c')
