-- Passage rg10-literary-structure-pov-p03
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('dcbba9d9-b980-5112-92c2-67d4dceaf0a4', 'rg10-literary-structure-pov-p03', (select id from public.skills where slug = 'read-g10-literary-structure-pov'), null,
        '9-12', $q$Moving Day, Told Backward$q$, $q$The last thing is the key on the counter,
bright as a coin no store will take.
I leave it there. The door clicks shut behind me,
and the hallway smells like someone else already.

Before that, the empty room: a pale square on the wall
where the calendar hung for nine years,
the carpet holding four dents
from the legs of a table that is now in a truck.

Before that, my brother and I carry the boxes
labeled KITCHEN, BOOKS and DO NOT CRUSH,
and we argue about which one is heavier
so we do not have to talk about anything else.

Before that, the night my mother sits us down
and says the word transfer, says the word Denver,
says it will be good for all of us,
and the radiator knocks as if it has something to add.

Before that, years of ordinary Tuesdays,
spaghetti, homework, the neighbor's dog
barking at the mail carrier on schedule,
a life too normal to notice.

And before that, the first day: I am four,
standing in this same doorway, holding a stuffed giraffe,
and my mother bends down and says, Look,
this is where we live now. And I believe her.$q$, 'draft')
