  ('87b8c2d4-3f06-5f85-9955-f8ae394e475a', null, (select id from public.skills where slug = 'read-g10-story-details-inference'), null, 'medium',
   $q$What does the weathervane mean when it tells the kite, "I go where the wind tells me, and so do you"?$q$, $q$[{"text":"The kite and the weathervane were both made by the same farmer.","is_correct":false,"misconception_token":"literal-reading"},{"text":"The kite should spend more time resting on the barn roof.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The weathervane secretly wishes it could fly with the kite.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The kite, like the weathervane, is controlled by forces outside itself.","is_correct":true}]$q$::jsonb, $q$The kite, like the weathervane, is controlled by forces outside itself.$q$, $q$The weathervane suggests the kite's freedom depends on the wind (and its string), just as its own turning does. Nothing the weathervane says shows that it envies the kite; it answers the kite's pity calmly.$q$, 'draft', 'c1a1a6bd-05b3-55c3-beb0-33d8d34d3ed7')
